-- =============================================================================
-- Vê AI · SQL Server / Azure SQL · Seed de demonstração
-- Mesmos dados do repositório database (tools/dataset.json): 3 regiões, 4 cidadãos,
-- 2 gestores, 20 descrições e 15 relatos. Datas relativas ao momento da carga.
-- Senha de todos os usuários: Veai@2026
-- Só insere se o banco estiver vazio (pode rodar quantas vezes quiser).
-- =============================================================================
IF NOT EXISTS (SELECT 1 FROM usuario)
BEGIN
    -- REGIAO (latitude/longitude = centro aproximado do bairro)
    SET IDENTITY_INSERT regiao ON;
    SET IDENTITY_INSERT regiao OFF;
    -- USUARIO
    SET IDENTITY_INSERT usuario ON;
    SET IDENTITY_INSERT usuario OFF;
    -- GESTOR_REGIAO
    -- DESCRICAO
    SET IDENTITY_INSERT descricao ON;
    SET IDENTITY_INSERT descricao OFF;
    -- RELATO (prioridade = peso da gravidade × (1 + apoios) + dias em aberto; 0 se finalizado)
    SET IDENTITY_INSERT relato ON;
    SET IDENTITY_INSERT relato OFF;
    -- APOIO_RELATO
    -- ATUALIZACAO_RELATO
END;
